function validate([text, words]) {
  if (typeof text !== 'string' || text.length < 1 || text.length > 100) return 'text has 1 to 100 characters.';
  if (!/^[a-z]+$/.test(text)) return 'text contains only lowercase letters.';
  if (!Array.isArray(words) || words.length < 1 || words.length > 20) return 'words has 1 to 20 strings.';
  for (const word of words) {
    if (typeof word !== 'string' || word.length < 1 || word.length > 50) return 'Each word has 1 to 50 characters.';
    if (!/^[a-z]+$/.test(word)) return 'Words contain only lowercase letters.';
  }
  if (new Set(words).size !== words.length) return 'The words must be distinct.';
  return null;
}

