function indexPairs(text, words) {
  const root = { next: new Map(), isWord: false };
  for (const word of words) {
    let node = root;
    for (const ch of word) {
      if (!node.next.has(ch)) {
        node.next.set(ch, { next: new Map(), isWord: false });
      }
      node = node.next.get(ch);
    }
    node.isWord = true;
  }

  const pairs = [];
  for (let i = 0; i < text.length; i++) {
    let node = root;
    for (let j = i; j < text.length; j++) {
      node = node.next.get(text[j]);
      if (node === undefined) {
        break;
      }
      if (node.isWord) {
        pairs.push([i, j]);
      }
    }
  }
  return pairs;
}

