function indexPairs(text, words) {
  const found = [];
  for (const word of words) {
    let at = text.indexOf(word);
    while (at !== -1) {
      found.push([at, at + word.length - 1]);
      at = text.indexOf(word, at + 1);
    }
  }
  return found.sort((a, b) => a[0] - b[0] || a[1] - b[1]);
}

