function generate(rand, size) {
  const pick = k => Math.floor(rand() * k);
  const alphabet = rand() < 0.7 ? 'ab' : 'abc';
  const randomWord = len => Array.from({ length: len }, () => alphabet[pick(alphabet.length)]).join('');
  const textLength = size === 'large' ? 90 + pick(11) : 1 + pick(12);
  const text = randomWord(textLength);
  const count = size === 'large' ? 20 : 1 + pick(5);
  const maxLength = size === 'large' ? 50 : 5;
  const words = new Set();
  let tries = 0;
  while (words.size < count && tries++ < 1000) {
    if (rand() < 0.6) {
      const start = pick(text.length);
      const len = 1 + pick(Math.min(maxLength, text.length - start));
      words.add(text.slice(start, start + len));
    } else {
      words.add(randomWord(1 + pick(maxLength)));
    }
  }
  return [text, [...words]];
}
